#include <cctype>
#include <string>
#include <vector>

static std::string lower(std::string s)
{
    for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    return s;
}

bool needsDebugRuntime(const std::vector<std::string>& dlls)
{
    for (const std::string& d : dlls)
    {
        const std::string l{ lower(d) };
        if (l == "msvcp140d.dll" || l == "vcruntime140d.dll" || l == "vcruntime140_1d.dll" || l == "ucrtbased.dll") return true;
    }
    return false;
}

bool isApiSet(const std::string& dll)
{
    const std::string l{ lower(dll) };
    return l.rfind("api-ms-", 0) == 0 || l.rfind("ext-ms-", 0) == 0;
}

unitTests:
TEST("a debug build") { CHECK(needsDebugRuntime({ "StoneMath.dll", "MSVCP140D.dll", "KERNEL32.dll" })); CHECK(needsDebugRuntime({ "ucrtbased.dll" })); }
TEST("a release build") { CHECK(!needsDebugRuntime({ "MSVCP140.dll", "VCRUNTIME140.dll", "KERNEL32.dll" })); CHECK(!needsDebugRuntime({})); }
TEST("API sets") { CHECK(isApiSet("api-ms-win-core-file-l1-1-0.dll")); CHECK(isApiSet("API-MS-Win-CRT-Runtime-l1-1-0.dll")); CHECK(isApiSet("ext-ms-win-ntuser-window-l1-1-0.dll")); }
TEST("not API sets") { CHECK(!isApiSet("kernel32.dll")); CHECK(!isApiSet("my-api-ms-thing.dll")); }

